-- ======================================================================
-- SSC CHSL 2017 - Positive Thinking (Actual PYQ)
-- ======================================================================
INSERT INTO passages (id, title, content, language, category, difficulty, exact_key_depressions, word_count, topic, source, ssc_exam_year)
VALUES (
  'a0000000-0000-0000-0000-000000000100',
  'Positive Thinking',
  $$Is positive thinking an inherent characteristic of a person or can it be developed in one's psyche? The opinions differ in answering this vital question. Some people believe that it can be inherited from parents, and cannot be developed. Others believe that like other qualities it can be developed with proper practice and guidance. Still some others hold the opinion that it is hereditary to some extent but can be acquired to some degree. There is also a section of people, who believe that all depends on circumstances or luck. We need to adopt a scientific approach to find an answer to the above question. No one can get success every time even after making efforts, nor can one fail constantly. Moreover, success has different meaning for different people. For some students, getting 60 per cent marks is success, for others it may not be sufficient. In a competitive examination, success means getting selected, whatever the percentage of marks. As for inheritance theory, since positive attitude is not a physical feature but a mental faculty, it cannot be purely hereditary. It can be developed. Moreover, parents play a major role in developing this quality of a child. A child, who watches his parents working hard, having faith in success through their words, behaviour and body language, is likely to develop a similar attitude. The children of short-tempered, over-cautious and nervous parents may assume similar characteristics when they grow up. Psychologists, therefore, prescribe a code of conduct for parents' behaviour in front of their children. They must exude confidence, self-belief and hope, especially in difficult situation, so that the children emulate these qualities. They must be taught the importance of being positive before, during and after the performance of a task. There is no better education for a child than watching his parents come out of a tough situation by means of earnest endeavours. Such success not only gives more joy but also increases self-confidence.$$,
  'english', 'ssc_chsl', 'hard', 2031, 309,
  'Psychology', 'SSC CHSL 2017 Skill Test', '2017'
);

-- ======================================================================
-- SSC CHSL 2018 - Stretching and Flexibility (Actual PYQ)
-- ======================================================================
INSERT INTO passages (id, title, content, language, category, difficulty, exact_key_depressions, word_count, topic, source, ssc_exam_year)
VALUES (
  'a0000000-0000-0000-0000-000000000101',
  'Stretching and Flexibility',
  $$Stretching a specific tendon or muscle can improve the elasticity of muscles, which in turn helps in achieving a comfortable muscle tone. There are several benefits of regular stretching, and it should be an integral part of every workout program. It not only helps increase your flexibility, which is an important part of fitness, but it can also improve your posture, body aches, reduce stress, and much more. One of the benefits of regular stretching is that it enhances flexibility. Being flexible has its own advantages, as it not only improves your day to day activities, but can also help delay the reduced mobility that comes with aging. Stretching on a regular basis can help increase your range of motion. You can either go for static or dynamic stretching as they both are effective when it comes to the increasing range of motion. According to the studies, proprioceptive neuromuscular facilitation or PNF type of stretching is more effective for immediate results. Regular stretching can not only help heal an existing back injury but can also prevent future back pain by reducing your risk for muscle strain and strengthening your back muscles. All the people who regularly go to the gym know how helpful stretching can be. Performing dynamic stretches prior to exercise in the gym can help prepare your muscles. Not only the gym, but it can also help you improve your performance in dance or an athletic event. It is only natural that your muscles get tense when you experience physical or emotional stress. This is because the tightening of your muscles is the response of the body towards stress. All you need to do is focus on the areas of your body where you feel the stress, such as your neck, shoulders, etc. and stretch those parts of your body.$$,
  'english', 'ssc_chsl', 'hard', 1751, 268,
  'Health and Fitness', 'SSC CHSL 2018 Skill Test', '2018'
);

-- ======================================================================
-- SSC CHSL 2019 - Iodine Fortification (Actual PYQ)
-- ======================================================================
INSERT INTO passages (id, title, content, language, category, difficulty, exact_key_depressions, word_count, topic, source, ssc_exam_year)
VALUES (
  'a0000000-0000-0000-0000-000000000102',
  'Iodine Fortification',
  $$Iodine fortification is what most countries rely on to encourage adequate dietary intake. In more than seventy countries that iodize salt generally serves as the major source of iodine intake. One fourth of a teaspoon of iodized salts has about hundred micrograms of iodine. Note that the salt used in processed foods, which is the major source of salt for most Americans typically does not contain iodine. If salt used in a processed food contains iodine, it will be listed in the ingredients list of that food. Focus on decreasing the amount of salt consumed from processed foods and get your sodium from iodized salt. Seaweed, saltwater fish and seafood are natural sources of dietary iodine. Dairy products also supply iodine in the diet at varying levels. During lactation, the breast concentrates iodine in milk so breastmilk tends be a good source of iodine as long as the iodine intake of a mother is adequate. Plants grown in iodine rich soil are also good sources. However, this is not a reliable source of iodine since there is no way of knowing whether produce purchased in grocery stores is grown in iodine rich soil or not. Iodized salt usually adds less than about three hundred micrograms iodine daily to the diet. Most multivitamin mineral supplements contain 150 micrograms of iodine. With the safe upper limit of daily iodine intake for adults set at 1,100 micrograms by the IOM it is unlikely to hit an excess amount when including a multivitamin and including natural sources of dietary iodine. The trend of eating less table salt, dairy and bread has some experts concerned that iodine deficiency could be on the rise again. Eating a healthy, balanced diet that includes iodine rich foods and iodized salt is key to good health.$$,
  'english', 'ssc_chsl', 'hard', 1752, 264,
  'Nutrition and Health', 'SSC CHSL 2019 Skill Test', '2019'
);

-- ======================================================================
-- SSC CHSL Mock - Union Budget and RBI Monetary Policy
-- ======================================================================
INSERT INTO passages (id, title, content, language, category, difficulty, exact_key_depressions, word_count, topic, source, ssc_exam_year)
VALUES (
  'a0000000-0000-0000-0000-000000000103',
  'Union Budget and RBI Policy',
  $$A number of measures were announced in Union Budget 2012 to augment supply and improve storage and warehousing facilities. Government launched a National Mission for Protein supplements in 2011 with allocation of Rs 300 crore. To broaden the scope of production of fish to coastal aquaculture, apart from fresh water aquaculture, the outlay in 2012 was stepped up to Rs 500 crore. Recently, Government permitted Foreign Direct Investment in multi brand retail trading. This will help consumers and farmers as it will improve the selling and purchasing facilities. Global economic and financial conditions continued to deteriorate during this period and with a sharper moderation in domestic growth, the growth inflation trade-off needs a revisit. In the assessment of the Reserve Bank of India, keeping in view the inflation in the country, further reduction in policy rates at this juncture, could accentuate inflationary pressures rather than supporting growth. Further, since the risk to inflation was also emanating from the high fiscal deficit, uncertainty in international prices of crude oil and structural imbalances in demand supply of food, particularly protein foods, a cautious monetary policy stand was preferable. However, the actions taken by the Government since September, particularly with regard to the increase in the administered prices of diesel, announcement of a fiscal road map with clear medium term fiscal deficit targets and initiatives to improve investor perception have created a favourable environment and have signalled a shift towards investment and capacity addition.$$,
  'english', 'ssc_chsl', 'hard', 1751, 269,
  'Economy and Budget', 'SSC CHSL Mock Test', '2024'
);

-- ======================================================================
-- LDC Typing - Technology and Automation (World Bank Report)
-- ======================================================================
INSERT INTO passages (id, title, content, language, category, difficulty, exact_key_depressions, word_count, topic, source, ssc_exam_year)
VALUES (
  'a0000000-0000-0000-0000-000000000110',
  'Technology and Automation',
  $$Technology could fundamentally disrupt the pattern of traditional economic path in developing countries. Automation threatens 69 per cent of the jobs in India, while 77 per cent in China, according to a World Bank research which has said that technology could fundamentally disrupt the pattern of traditional economic path in developing countries. As we continue to encourage more investment in infrastructure to promote growth, we also have to think about the kinds of infrastructure that countries will need in the economy of the future. We all know that technology has and will continue to fundamentally reshape the world, World Bank president Jim Kim said. But the traditional economic path from increasing productivity of agriculture to light manufacturing and then to full-scale industrialization may not be possible for all developing countries, Mr. Kim said in response to a question at the Brookings Institute during a discussion on extreme poverty on Tuesday. In large parts of Africa, it is likely that technology could fundamentally disrupt this pattern. Research based on World Bank data has predicted that the proportion of jobs threatened in India by automation is 69 per cent, in China it is 77 per cent and in Ethiopia, the percentage of jobs threatened by automation is 85 per cent, he said. Now, if this is true, and if these countries are going to lose these many jobs, we then have to understand what paths to economic growth will be available for these countries and then adapt our approach to infrastructure accordingly, Mr. Kim said. Automation is not just a threat for India, it is so all over the world.$$,
  'english', 'ssc_cgl', 'hard', 1752, 269,
  'Technology and Economy', 'LDC Typing Collection', '2024'
);

-- ======================================================================
-- LDC Typing - India at UN Security Council
-- ======================================================================
INSERT INTO passages (id, title, content, language, category, difficulty, exact_key_depressions, word_count, topic, source, ssc_exam_year)
VALUES (
  'a0000000-0000-0000-0000-000000000111',
  'India at UN Security Council',
  $$India strongly criticized an unresponsive Security Council on Wednesday for being indecisive on sanctioning leaders of organizations it itself designates as terrorist entities after China extended its technical hold on India's bid for a UN ban against JeM chief Masood Azhar. India's Permanent Representative to the UN Ambassador Syed Akbaruddin told the UN General Assembly that the 15-nation Security Council, the principal organ tasked with the maintenance of peace and security, has in a variety of ways become unresponsive to the needs of our time and ineffective to meeting the challenges it is confronted with. The Council has failed to sanction leaders of terrorist entities despite those entities being listed by the Council itself. He said that the Security Council must reflect contemporary realities and called for urgent reform of the United Nations. India has been a strong advocate for the reform of the Security Council and has consistently raised the issue of expansion in both permanent and non-permanent categories of membership.$$,
  'english', 'ssc_cgl', 'hard', 1753, 264,
  'International Relations', 'LDC Typing Collection', '2024'
);

-- ======================================================================
-- LDC Typing - GSAT-18 / ISRO Launch
-- ======================================================================
INSERT INTO passages (id, title, content, language, category, difficulty, exact_key_depressions, word_count, topic, source, ssc_exam_year)
VALUES (
  'a0000000-0000-0000-0000-000000000112',
  'GSAT-18 Communication Satellite',
  $$India's latest communication satellite GSAT-18 was successfully launched into orbit by the European space agency Arianespace's rocket Ariane 5 from the spaceport of Kourou in French Guiana. The launch was conducted under favourable weather conditions at Kourou, a spaceport located along the coast of South America. GSAT-18, built by the Indian Space Research Organisation, aims at providing telecommunications services for the country by strengthening ISRO's current fleet of 14 operational telecommunication satellites. The satellite has a lift-off mass of about 3,404 kg and will be placed in a geostationary orbit. It carries communication payloads in normal C-band, extended C-band and Ku-band. The satellite will provide services to the whole of India including the Andaman and Nicobar Islands and Lakshadweep. This launch marked another significant milestone in India's space programme and demonstrated the strong partnership between India and France in the field of space exploration. The successful deployment of GSAT-18 will enhance India's capabilities in telecommunications, broadcasting and broadband services across the country.$$,
  'english', 'ssc_cgl', 'medium', 1750, 260,
  'Space Technology', 'LDC Typing Collection', '2024'
);

-- ======================================================================
-- LDC Typing - Fiscal Year Change
-- ======================================================================
INSERT INTO passages (id, title, content, language, category, difficulty, exact_key_depressions, word_count, topic, source, ssc_exam_year)
VALUES (
  'a0000000-0000-0000-0000-000000000113',
  'Fiscal Year Change Proposal',
  $$Change would be needlessly disruptive to Maharashtra. The Maharashtra government has expressed its reluctance to fall in line with the Centre's plan to change the Indian financial year from April-March to January-December. It has communicated to New Delhi that the change would be needlessly disruptive to the state of Maharashtra at a time when fixing the economy, and implementing GST and new financial norms should be the priority. Most countries around the world prefer the January-December fiscal year, but India remains one of the few exceptions. The central government had set up a committee to examine the feasibility of shifting to a January-December financial year to align India's fiscal calendar with global practices. The committee had submitted its report recommending the change, but several state governments expressed concerns about the logistical challenges and administrative costs involved in such a transition. The opposition to the change highlights the complexity of harmonizing fiscal policies across different levels of government in a federal system like India.$$,
  'english', 'ssc_cgl', 'medium', 1751, 257,
  'Economy and Fiscal Policy', 'LDC Typing Collection', '2024'
);

-- ======================================================================
-- LDC Typing - Unemployment and Rural Employment
-- ======================================================================
INSERT INTO passages (id, title, content, language, category, difficulty, exact_key_depressions, word_count, topic, source, ssc_exam_year)
VALUES (
  'a0000000-0000-0000-0000-000000000114',
  'Unemployment and Rural Development',
  $$Sir, more jobs are, therefore, to be created in the rural hinterland. Agriculture labour will have to be paid better wages. We always are lethargic in all such matters. But it is only then we can put more purchasing power in the hands of the lower income groups and then only their demand becomes more effective, attracting greater flow of private investment to goods that are needed by these people and thus creating and generating employment. I must point out that the growth and development of small towns has been neglected. In the decades of our planning, we have been rather neglecting the growth of small and medium towns. What is the result? From the rural areas, the people jump over these small and medium towns and also villages taken as a cluster to be developed through proper policies. We will then see that not only we check this undesirable migration towards bigger cities but then these small towns and medium sized towns will also help a lot in absorbing this migration. I must also emphasize the need for greater attention towards the co-operative rural industries. We can take cluster of all villages. That can be combined and then they can form co-operatives for production by pooling their resources and expertise. This could provide a lot of additional work. The training programmes in the rural areas need also to be re-oriented. We must see that training and educational institutions in rural areas are to impart such low level training skills which would equip the trainees to take up work which is related either to agriculture or to industry within the rural areas. So such types of our policies are needed. A lot still can be said, but to conclude, by summarizing the points which I was making, what I say is that we cannot be a mere spectator to this question of menacing proportions which unemployment has assumed.$$,
  'english', 'ssc_cgl', 'hard', 1874, 289,
  'Employment and Rural Development', 'LDC Typing Collection', '2024'
);

-- ======================================================================
-- SSC CGL DEST - Life is Action, Not Contemplation
-- ======================================================================
INSERT INTO passages (id, title, content, language, category, difficulty, exact_key_depressions, word_count, topic, source, ssc_exam_year)
VALUES (
  'a0000000-0000-0000-0000-000000000120',
  'Life is Action, Not Contemplation',
  $$Life offers many opportunities to us to succeed and see it closely. But action is required for it. Goethe, a German philosopher rightly remarked that life is action, not contemplation. Even Charles Darwin proved that this life is a continuous struggle for the survival of the fittest. One who is not suitable perishes. This is nature's law. Action is necessary to adjust ourselves in any possible circumstances. Dreams are the necessary propellers but life itself is not merely a dream or reverie. Sitting on a chair, brooding, man would never have been able to reach the moon. But man thought, imagined and strove. Consequently we reached the hitherto unknown heights. Thus a life of thought and reflection will be futile if man does not try to make it come true in real life. The saddest day of my life was the Diwali Day. Diwali is considered to be a happy festival and till last Diwali, it was my favourite festival. On last Diwali, my sister, my brother and I were busy lighting the fireworks. I was holding a fuljhari in my hand and unfortunately my younger brother, who was standing just beside me, had a cracker in his hand. This cracker caught fire and a very loud explosion was heard which shook my sister and me. After that, we all could think of nothing else than blood stained cotton, bandage, dettol etc. My cousin took my brother to the doctor where he got 14 stitches in his forefinger and thumb. But at home, everybody kept cursing and blaming me for the mishap. That night, I could not sleep and I cried a lot. For next few days, I bore the burden of this blame for being responsible for this unfortunate incident. I felt deeply guilty conscious which I was able to overcome after a long time.$$,
  'english', 'ssc_cgl', 'medium', 2071, 321,
  'Life Lessons', 'SSC CGL DEST Collection', '2024'
);

